import{_ as a,a0 as h,w as d,s as l,ao as e,I as p,x as n,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220714 Fixing -Command -python- not found- Error in Ubuntu Linux","title":"修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤","tag":"202207","desc":""},"relativePath":"202207/20220714 Fixing -Command -python- not found- Error in Ubuntu Linux.md","filePath":"[post].md"}'),u={name:"202207/20220714 Fixing -Command -python- not found- Error in Ubuntu Linux.md"};function r(y,t,g,b,c,k){const o=h("Link");return d(),l("div",null,[t[18]||(t[18]=e(`<h1 id="修復-ubuntu-linux-中-command-python-not-found-的錯誤" tabindex="-1">修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤 <a class="header-anchor" href="#修復-ubuntu-linux-中-command-python-not-found-的錯誤" aria-label="Permalink to “修復 Ubuntu Linux 中 “Command ‘python’ not found” 的錯誤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/30/071627r176w1k1y5dkkw6w.jpg" alt=""></p><p>如何在 Linux 終端中運行一個 Python 程序？像這樣，對嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python program.py</span></span></code></pre></div><p>然而，如果你試圖在 Ubuntu（和其他一些發行版）中使用 <code>python</code> 命令，它會拋出一個錯誤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command ‘python’ not found, did you mean:</span></span>
<span class="line"><span>command ‘python3’ from deb python3</span></span>
<span class="line"><span>command ‘python’ from deb python-is-python3</span></span></code></pre></div><p>如果你注意這個錯誤信息，它説明了很多東西。<strong>這裏的 <code>python</code> 命令實際上是 <code>python3</code></strong>。</p><p>如果你不理解，不用擔心。我將在這裏詳細解釋。</p><h3 id="為什麼在-ubuntu-上沒有發現-python-命令" tabindex="-1">為什麼在 Ubuntu 上沒有發現 python 命令？ <a class="header-anchor" href="#為什麼在-ubuntu-上沒有發現-python-命令" aria-label="Permalink to “為什麼在 Ubuntu 上沒有發現 python 命令？”">​</a></h3><p>這是因為 Python 語言不是以 <code>python</code> 的形式安裝的，而是以 <code>python3</code> 或 <code>python2</code> 的形式安裝的（在一些老的 Ubuntu 版本中）。</p><p>在遙遠的過去的某個時間點，Python 實際上是作為 <code>python</code> 包/可執行文件提供的。當 Python 發佈第二版時，Ubuntu 和其他發行版不得不同時支持 Python 1.x 和 2.x 版本。</p><p>因此，他們將較新的 Python 版本命名為 <code>python2</code>，以區分這兩個版本。其他應用或庫也在其代碼中指定 <code>python</code> 或 <code>python2</code>。</p><p>最終，Python 1 版本被完全停用，但軟件包繼續被命名為 <code>python2</code>。</p><p>類似地，當 Python 3 版本發佈時，發行版開始同時提供 <code>python2</code> 和 <code>python3</code> 包。</p><p>Python 2 不再被支持，Python 3.x 是你在 Ubuntu 上安裝的版本。該軟件包仍被命名為 <code>python3</code>。</p><p><strong>總結一下，你已經在 Ubuntu 上安裝了 Python。它是以 <code>python3</code> 軟件包方式使用的。</strong></p>`,16)),p("p",null,[t[1]||(t[1]=n("那麼，當你 ",-1)),s(o,{href:"https://itsfoss.com/bash-command-not-found/"},{default:i(()=>[...t[0]||(t[0]=[n("在 Ubuntu 上看到 “Python command not found” 的錯誤",-1)])]),_:1}),t[2]||(t[2]=n(" 時，你有什麼選擇？讓我來介紹一下。",-1))]),t[19]||(t[19]=e(`<h3 id="確保你的系統中已經安裝了-python" tabindex="-1">確保你的系統中已經安裝了 Python <a class="header-anchor" href="#確保你的系統中已經安裝了-python" aria-label="Permalink to “確保你的系統中已經安裝了 Python”">​</a></h3><p>它應該已經安裝了，但仔細檢查一下也無妨。</p><p>Ubuntu 18.04 也有 Python 2，但 20.04 及更高版本只有 Python 3。不過，你有哪個版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type python python2 python3</span></span></code></pre></div><p>正如你在下面的截圖中看到的，我的系統上安裝了 Python 3 版本。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/check-python-version-ubuntu.png" alt="Checking Python version in Ubuntu"></p><p>如果你沒有安裝任何 Python 版本，你可以用以下命令安裝 Python 3 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install python3</span></span></code></pre></div><h3 id="使用-python3-而不是-python" tabindex="-1">使用 python3 而不是 python <a class="header-anchor" href="#使用-python3-而不是-python" aria-label="Permalink to “使用 python3 而不是 python”">​</a></h3><p>如果對你來説不是太麻煩，在需要的地方使用 <code>python3</code> 命令而不是 <code>python</code>。</p><p>想檢查已安裝的 Python 版本嗎？請這樣輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python3 --version</span></span></code></pre></div><p>然後你會在輸出中得到版本的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ python3 --version</span></span>
<span class="line"><span>Python 3.10.4</span></span></code></pre></div><p>如果你必須運行一個 Python 程序，請像這樣執行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python3 program.py</span></span></code></pre></div><p>這在大多數情況下應該對你有用。但是，如果你使用的是一些（舊的）Python 應用，期望在其代碼中運行 Python 可執行文件，你就會有問題。別擔心，你也可以繞過它。</p><h3 id="將-python3-鏈接為-python" tabindex="-1">將 python3 鏈接為 python <a class="header-anchor" href="#將-python3-鏈接為-python" aria-label="Permalink to “將 python3 鏈接為 python”">​</a></h3><p>你可以在你的 <code>.bashrc</code> 文件中創建一個永久別名，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias python=&#39;python3&#39;</span></span></code></pre></div><p>這樣，你可以運行 <code>python</code> 命令，而你的系統運行 <code>python3</code>。</p><p>這在大多數情況下都會起作用，除非某些程序期望運行 <code>/usr/bin/python</code>。現在，你可以在 <code>/usr/bin/python</code> 和 <code>/usr/bin/python3</code> 之間建立符號鏈接，但對於 Ubuntu 用户來説，存在一個更簡單的選擇。</p><p>對於 Ubuntu 20.04 和更高版本，如果你安裝了 <code>python-is-python3</code> 軟件包，你有一個軟件包可以自動完成所有鏈接創建。這也是原始錯誤信息所提示的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install python-is-python3</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/install-python-is-python3-ubuntu.png" alt="install python is python3 ubuntu"></p><p>你可以看到符號鏈接已經被創建，你可以使用 <code>python</code> 命令（實際上是運行 <code>python3</code>），沒有任何問題。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/checking-python-ubuntu.png" alt="checking python ubuntu"></p><p>我希望這能澄清 Ubuntu 中 Python 軟件包的問題。如果你有任何問題或建議，請告訴我。</p><hr>`,29)),p("p",null,[t[4]||(t[4]=n("via: ",-1)),s(o,{href:"https://itsfoss.com/python-not-found-ubuntu/"},{default:i(()=>[...t[3]||(t[3]=[n("https://itsfoss.com/python-not-found-ubuntu/",-1)])]),_:1})]),p("p",null,[t[9]||(t[9]=n("作者：",-1)),s(o,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...t[5]||(t[5]=[n("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=n(" 選題：",-1)),s(o,{href:"https://github.com/lkxed"},{default:i(()=>[...t[6]||(t[6]=[n("lkxed",-1)])]),_:1}),t[11]||(t[11]=n(" 譯者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[7]||(t[7]=[n("geekpi",-1)])]),_:1}),t[12]||(t[12]=n(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[15]||(t[15]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[n("Linux中國",-1)])]),_:1}),t[17]||(t[17]=n(" 榮譽推出",-1))])])}const C=a(u,[["render",r]]);export{x as __pageData,C as default};
